<template><section class="care-access"><h3>Guardians & shared care messages</h3><p>Provider messages are a group conversation for {{clientName}}. These people can read and reply:</p><p v-if="loading">Loading access…</p><p v-if="error" role="status">{{error}}</p><ul><li v-for="p in participants" :key="p.id"><strong>{{p.name}}{{Number(p.id)===Number(userId)?' (you)':''}}</strong><span>{{p.role==='guardian'?'Guardian':p.role==='client'?'Client':p.role==='provider'?'Provider':'Care team'}}</span></li></ul><p>Access follows the permissions on this client’s record. Contact the care team if this list needs review.</p><p>Your saved card and billing or technology support requests stay attached to your account. A document shared only with you is not automatically shared with another guardian.</p><button @click="$emit('messages')">Open shared care conversation →</button></section></template>
<script setup>
import {ref,watch,onBeforeUnmount} from 'vue';import api from '../../services/api';
const props=defineProps({clientId:[Number,String],clientName:String,userId:[Number,String]});defineEmits(['messages']);
const participants=ref([]),loading=ref(false),error=ref('');let seq=0;
watch(()=>props.clientId,async id=>{const own=++seq;participants.value=[];error.value='';loading.value=true;try{const{data}=await api.get(`/guardian-portal/clients/${id}/care-access`,{skipGlobalLoading:true});if(own===seq)participants.value=data.participants||[];}catch{if(own===seq)error.value='Shared messaging access is not available right now. Contact the care team to review it.';}finally{if(own===seq)loading.value=false;}},{immediate:true});onBeforeUnmount(()=>seq++);
</script>
<style scoped>.care-access{border:1px solid #c9d8e7;border-radius:12px;padding:20px;margin:16px 0;background:#f4f8fc}.care-access ul{list-style:none;padding:0}.care-access li{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #d7e3ef}.care-access p{font-size:14px;line-height:1.6}.care-access span{color:#526784}.care-access button{font:inherit;background:white;color:#16457c;border:1px solid #bbcede;border-radius:8px;padding:10px;cursor:pointer}</style>
